/**
 * Notion Node - Version 3
 * Discriminator: resource=dataSource, operation=get
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Get a data source */
export type NotionV3DataSourceGetParams = {
  resource: 'dataSource';
  operation: 'get';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * The Notion data source to retrieve
 * @searchListMethod getDataSources
 * @default {"mode":"list","value":""}
 */
    dataSourceId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint When true, each data source returns only id, name, and url. Set false to retain native fields such as properties, which describes the data source schema. To read page values, use Database Page operations. Match verification output fixtures to the selected output mode.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
};

export type NotionV3DataSourceGetOutput = {
  id?: string;
  name?: string;
  url?: string;
};

export type NotionV3DataSourceGetNode = {
  type: 'n8n-nodes-base.notion';
  version: 3;
  config: NodeConfig<NotionV3DataSourceGetParams> & { credentials?: Credentials };
  output?: Items<NotionV3DataSourceGetOutput>;
};